mapper.select:
select o.ORGNAME,r.unit as orgid from TBL_CONTROLMATRIX c left join tbl_risk_coping co on c.RISKCOPINGID=co.RISKCOPINGID left join tbl_risk r on r.riskid=co.RISKID left join TBL_ORGANIZATION o on o.orgid=r.unit where r.riskid is not null
and r.unit!=#{orgid}
group by o.ORGNAME,r.unit

select * from TBL_CONTROLMATRIX c left join tbl_risk_coping co on c.RISKCOPINGID=co.RISKCOPINGID left join tbl_risk r on r.riskid=co.RISKID where r.riskid is not null
and r.unit=#{orgid}
and extjson LIKE concat(concat('%',#{type}),'%')
